/// <summary>
/// [packageUrl] is the blob SAS URL the app already uploaded the counted-quantity package to
/// via the public `GetAzureWriteUrl` OData action - see CountingJournalRepository.submitCounts.
/// </summary>
[DataContractAttribute]
class HSMobileOpsImportCountsRequest
{
    DataAreaId       dataAreaId;
    InventJournalId  journalId;
    str              packageUrl;

}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('JournalId')]
public InventJournalId parmJournalId(InventJournalId _value = journalId)
{
    journalId = _value;
    return journalId;
}

[DataMemberAttribute('PackageUrl')]
public str parmPackageUrl(str _value = packageUrl)
{
    packageUrl = _value;
    return packageUrl;
}
